2	/**
3	 * Launch cc-wechat browser-based QR login.
4	 * Uses the browser mode: starts a local HTTP server and opens Chrome
5	 * with a proper QR code image.
6	 */
7	import { loginBrowser } from 'file:///C:/Users/yvan1/AppData/Local/npm-cache/_npx/19953a4e823081bf/node_modules/cc-wechat/dist/auth.js';
8	import { saveAccount } from 'file:///C:/Users/yvan1/AppData/Local/npm-cache/_npx/19953a4e823081bf/node_modules/cc-wechat/dist/store.js';
9	
10	console.log('正在启动浏览器登录页面...\n');
11	try {
12	  const result = await loginBrowser();
13	  saveAccount({
14	    token: result.token,
15	    baseUrl: result.baseUrl ?? '',
16	    botId: result.accountId.replace(/@/g, '-').replace(/\./g, '-'),
17	    savedAt: new Date().toISOString(),
18	  });
19	  console.log('\n✅ 登录成功！账号已保存。');
20	  console.log('Bot ID:', result.accountId);
21	  console.log('\n启动 Claude Code 时使用:');
22	  console.log('  claude --dangerously-load-development-channels server:wechat-channel');
23	} catch (err) {
24	  console.error('登录失败:', err.message);
25	  process.exit(1);
26	}
