1	import type { ILinkClient } from './ilink-client'
2	import type { WeixinMessage } from './types'
3	
4	export async function startPoller(
5	  client: ILinkClient,
6	  initialCursor: string,
7	  onMessage: (msg: WeixinMessage) => void,
8	  signal: AbortSignal,
9	  onCursor?: (cursor: string) => void,
10	): Promise<void> {
11	  let cursor = initialCursor
12	
13	  while (!signal.aborted) {
14	    try {
15	      const response = await client.getUpdates(cursor)
16	
17	      if (response.ret !== undefined && response.ret !== 0) {
18	        await new Promise(r => setTimeout(r, 5000))
19	        continue
20	      }
21	
22	      cursor = response.get_updates_buf
23	      onCursor?.(cursor)
24	
25	      for (const msg of response.msgs) {
26	        onMessage(msg)
27	      }
28	    } catch (err) {
29	      if (signal.aborted) break
30	      await new Promise(r => setTimeout(r, 5000))
31	    }
32	  }
33	}
